from pathlib import Path
import hashlib,json,numpy as np,polars as pl
ROOT=Path(__file__).resolve().parents[3]; HERE=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
MP=ROOT/'Claude Version/experiments/step254_mechanical_tensor_20260917/step254_features.parquet'; CTX=ROOT/'goal_top5_20260919/foundation_citation35/context.npz'; REF=ROOT/'Codex Resume/experiments/tabm_citation_pilot_20260919/reference.parquet'
z=np.load(CTX,allow_pickle=False); raw=pl.read_parquet(MP); rawcols=[c for c in raw.columns if c not in ['pair_id','hand_id']]; assert len(rawcols)==662
f=pl.read_parquet(HERE/'features.parquet'); support=['ct_pre_count','ct_post_count','ct_pre_support','ct_post_support','ct_pre_available','ct_post_available']; residual=['ct_pre_sum','ct_post_sum','ct_pre_max','ct_post_max']
train=f.filter(pl.col('split')=='train').select('pair_id','hand_id',*support,*residual).join(raw,on=['pair_id','hand_id'],validate='1:1').sort('pair_id','hand_id'); assert train.height==10438 and np.array_equal(train['pair_id'].to_numpy(),z['train_pair_ids'])
train=train.with_columns(pl.lit('train').alias('split'),pl.Series('target',z['yfull'].astype(np.float32)))
auditkeys=pl.DataFrame({'pair_id':z['pair_ids'],'hand_id':z['hand_ids']});audit=auditkeys.join(f.filter(pl.col('split')=='held_query').drop('split'),on=['pair_id','hand_id'],validate='1:1').join(raw,on=['pair_id','hand_id'],validate='1:1').with_columns(pl.lit('audit').alias('split'),pl.lit(None,dtype=pl.Float32).alias('target'));assert audit.height==940
cols=['pair_id','hand_id','split','target']+rawcols+support+residual; combined=pl.concat([train.select(cols),audit.select(cols)]); assert combined.height==11378 and combined.columns==cols
# Raw missing convention inherited by the fixed context: nonfinite/null raw values become zero.
combined=combined.with_columns(pl.col(rawcols).fill_nan(0).fill_null(0)); assert combined.select(pl.struct('split','pair_id','hand_id').n_unique()).item()==combined.height
path=HERE/'clean_features.parquet';combined.write_parquet(path)
base=json.loads((HERE/'manifest.json').read_text()); labels=pl.read_csv(ROOT/'data/development_labels.csv'); ref=pl.read_parquet(REF,columns=['pair_id','hand_id','table_id']); auditp=set(ref['table_id']); auditpairs=set(ref['pair_id']); auditplayers=set(labels.filter(pl.col('pair_id').is_in(list(auditpairs)))['player_1'])|set(labels.filter(pl.col('pair_id').is_in(list(auditpairs)))['player_2']); audithands=set(ref['hand_id'])
cache=pl.read_parquet(sorted((ROOT/'reports/conditional-action-experiment/action-cache').glob('*.parquet')),columns=['pair_id','hand_id','table_id']); permitted=cache.filter(~pl.col('table_id').is_in(list(auditp))); trainpairs=set(permitted['pair_id']); trainplayers=set(labels.filter(pl.col('pair_id').is_in(list(trainpairs)))['player_1'])|set(labels.filter(pl.col('pair_id').is_in(list(trainpairs)))['player_2']); trainhands=set(permitted['hand_id'])
over={'table_overlap':len(set(permitted['table_id'])&auditp),'player_overlap':len(trainplayers&auditplayers),'physical_hand_overlap':len(trainhands&audithands)}; assert over=={'table_overlap':0,'player_overlap':0,'physical_hand_overlap':0}
resid=pl.read_parquet(HERE/'nested_residuals.parquet'); line={}
for name in ['fold0','fold1','fold2','final']:
 m=base['models'][name]; scorep=base['audit_excluded_pools'] if name=='final' else [p for p,v in base['fold_assignment'].items() if v==int(name[-1])]
 score=resid.filter(pl.col('policy')==name); line[name]={'training_pools':m['training_pools'],'score_pools':sorted(score['table_id'].unique().to_list()),'training_rows':m['training_rows'],'scored_rows':score.height,'training_players_sha256':hashlib.sha256('\n'.join(m['training_players']).encode()).hexdigest(),'score_players_sha256':hashlib.sha256('\n'.join(sorted(score['actor'].unique())).encode()).hexdigest(),'training_hands_sha256':m['training_hands_sha256'],'score_hands_sha256':hashlib.sha256('\n'.join(sorted(score['hand_id'].unique())).encode()).hexdigest(),'model_sha256':m['model_sha256'],'pool_overlap':len(set(m['training_pools'])&set(scorep)),'audit_pool_training_overlap':len(set(m['training_pools'])&auditp)}
 assert line[name]['pool_overlap']==0 and line[name]['audit_pool_training_overlap']==0
(HERE/'lineage.json').write_text(json.dumps({'fits':line,'global_overlap':over,'audit_players':len(auditplayers),'audit_hands':len(audithands),'permitted_training_players':len(trainplayers),'permitted_training_hands':len(trainhands)},indent=2)+'\n')
manifest={'artifact':'clean_features.parquet','artifact_sha256':sha(path),'raw_source':str(MP),'raw_source_sha256':sha(MP),'raw_features':rawcols,'support_features':support,'residual_features':residual,'ordered_columns':cols,'rows':combined.height,'train_rows':10438,'audit_rows':940,'train_pairs':85,'audit_pairs':47,'train_pools':71,'audit_sp_pools':43,'old_artifact_used':False,'fallback_used':False,'zero_missing_raw':True,'excluded_audit_pools':104,**over,'nested_reference_fits':4,'bins_training_only':True,'support_semantics':{'pre_count':'ct_pre_count','post_count':'ct_post_count','pre_support':'ct_pre_support','post_support':'ct_post_support','pre_available':'ct_pre_available','post_available':'ct_post_available'},'residual_semantics':{'pre_sum':'ct_pre_sum','post_sum':'ct_post_sum','pre_max':'ct_pre_max','post_max':'ct_post_max'},'lineage_manifest':'lineage.json','lineage_sha256':sha(HERE/'lineage.json'),'upstream_manifest_sha256':sha(HERE/'manifest.json'),'protocol_sha256':sha(HERE/'PROTOCOL.md'),'quality_read':False,'downstream_fit':False}
(HERE/'clean_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps({k:v for k,v in manifest.items() if k not in ['raw_features','ordered_columns']},indent=2))
